BOUNDARIES = [
    ("little-population-boundary", "Little's law requires a matched population", "Occupancy, arrival/departure throughput, and residence time must refer to the same stable boundary and packet population; offered arrivals cannot replace admitted throughput when losses or rejected work change that population.", "admitted-throughput"),
    ("mm1-model-boundary", "M/M/1 formulas are model claims", "The stated stationary FCFS tail and mean formulas use independent Poisson arrivals, independent exponential service, one work-conserving server, infinite capacity, and lambda<mu; bursty correlated traffic or finite-buffer loss needs a different model.", "rate-gap"),
    ("pk-not-tail-law", "Second moment controls a particular mean", "The M/G/1 waiting formula assumes independent Poisson arrivals, iid service, nonpreemptive FCFS service without vacations, finite moments, and stable load; it is not a universal tail distribution or a formula for arbitrary correlated arrivals.", "service-second-moment"),
    ("fanout-independence", "Fanout probability needs the joint distribution", "A wait-for-all completion time is a maximum regardless of dependence, but the product F(t)^n requires independent identically distributed child times; shared bottlenecks and common pauses can violate that assumption.", "fanout-tail"),
    ("serialization-is-not-path-time", "Wire serialization is one latency component", "B/C accounts only for the specified wire work on a constant-rate link; propagation, queueing, endpoint processing, and overhead outside B must be added separately rather than silently disappearing.", "serialization-delay"),
    ("aqm-needs-responsive-loop", "Queue feedback and scheduling have different jobs", "AQM chooses congestion signals while a scheduler chooses service order; signaling alone does not guarantee bandwidth fairness, remove all overload from unresponsive senders, or eliminate feedback delay and capacity limits.", "aqm"),
    ("codel-profile", "CoDel thresholds are not hard packet deadlines", "RFC 8289's Experimental controller uses a persistence interval and a post-dequeue backlog guard; the recommended 5 ms TARGET and 100 ms INTERVAL are a specified Internet setting, not a universal low-latency SLA.", "codel-interval"),
    ("fq-hash-and-byte-service", "Flow buckets still share physical service", "RFC 8290 hashing can collide, byte deficits permit packet-sized overshoot, and flows still share one link; flow queueing does not guarantee per-host equality, exact instantaneous bandwidth shares, or isolation from all cross traffic.", "flow-isolation"),
    ("pacing-physical-boundary", "A nominal pacing schedule may be recoalesced", "Timer granularity, transmit offload, and downstream scheduling can turn distinct nominal departures into a burst; a claim about burst reduction must identify the actual observed send or bottleneck boundary.", "packet-spacing"),
    ("rdmap-completion-boundary", "Placement delivery and application completion differ", "RFC 5040 Section 5.5 states that generic local Write or Send completion does not guarantee arrival in the remote ULP buffer or examination there; operation-specific delivery and same-stream ordering rules govern safe inspection, while a remote application commit requires its own evidence.", "remote-app-work"),
    ("bypass-profile-boundary", "Kernel bypass names a selected fast path", "The DPDK direct-hardware profile excludes kernel-mediated virtual drivers and does not remove OS setup, registration, resource management, or application protocol work; polling versus interrupt behavior must be stated for the actual configured queue.", "user-pmd"),
    ("tx-admission-not-wire-proof", "Transmit queue admission is not peer receipt", "DPDK transmit-burst acceptance transfers the accepted packet buffers to the PMD's queueing responsibility; it is not proof they are already on the wire or consumed by a remote application, and unaccepted packets remain caller-owned.", "tx-admission"),
]

EXAMPLES = [
    ("little-twenty-packets", "A mean occupancy implies a mean residence time", "A constructed stable lossless system averages 20 admitted packets inside its chosen boundary and completes 1000 of that same population per second. Little's law gives mean residence 20/1000=0.020 seconds, or 20 ms; those two averages do not determine its ninety ninth percentile.", ["mean-system", "admitted-throughput", "mean-sojourn", "response-percentile"]),
    ("mm1-near-capacity", "Ninety percent load has a much larger tail than its service time", "A constructed stationary FCFS M/M/1 server has lambda=900 packets/s and mu=1000 packets/s with independent Poisson arrivals and exponential service. Mean system time is 1/100=10 ms; its ninety ninth percentile is -ln(0.01)/100 seconds, about 46.1 ms, while own mean service is only 1 ms.", ["arrival-rate", "service-rate", "rate-gap", "mean-sojourn", "response-percentile"]),
    ("same-mean-different-variance", "Equal utilization need not mean equal waiting", "At 500 Poisson arrivals/s and mean service 1 ms, two independent FCFS M/G/1 models both have rho=0.5. Deterministic service has E[S squared]=0.000001 seconds squared and mean wait 0.5 ms; exponential service has twice that second moment and mean wait 1 ms. This compares the mean under P-K assumptions, not every tail percentile.", ["arrival-rate", "utilization", "service-second-moment", "mg1-wait"]),
    ("fifo-wire-accounting", "Waiting bits and own bits consume different time", "In a constructed constant-rate FIFO link model, 12000 wire bits remain ahead of a new 6000-bit packet and the link serves 6000000 bits/s. The new packet waits 2 ms and then serializes for 1 ms. Propagation and host work were not included in either calculation.", ["fifo-work-ahead", "packet-wire-size", "link-rate", "queue-delay", "serialization-delay"]),
    ("fanout-amplifies-threshold-risk", "A rare independent child delay becomes common across a large fanout", "At a fixed threshold t, each of 100 independent identically distributed child responses has F(t)=0.99. A parent requiring all responses exceeds t with probability 1-0.99^100, about 63.4 percent. Sharing a common queue can invalidate the independence assumption even though the completion barrier still waits for the last response.", ["fanout-count", "branch-cdf", "fanout-tail", "response-barrier"]),
    ("window-and-rtt-bound", "A fast link can still be constrained by outstanding credit", "A constructed lossless window model has 65536 payload bytes of usable outstanding credit and a constant acknowledgment RTT of 0.1 seconds. Its window-based upper bound is 8*65536/0.1=5242880 bits/s, about 5.24 Mbit/s, even if the physical link could serialize faster. This is not a promise that other limits allow that rate.", ["flight-budget", "round-trip-delay", "window-rate-bound"]),
    ("incast-small-flight-loss", "Many short replies can overflow one shared egress", "Sixteen constructed replies each contribute 10000 accounted bytes during one burst. The egress can serve 32000 bytes in that interval and has only 64000 bytes free, so it cannot retain all 160000 arriving bytes. If a dropped short TCP response lacks qualifying fast-retransmit evidence and has no newer early-recovery mechanism, its timeout wait can hold up the parent's all-response barrier.", ["synchronized-fan-in", "burst-volume", "incast-loss", "rto-wait", "response-barrier"]),
    ("codel-equality-and-persistence", "Equal-to-target first arms a deadline", "With RFC 8289 TARGET=5 ms and INTERVAL=100 ms, an initially unarmed helper observes sojourn exactly 5 ms at time 200 ms and remaining backlog above maxpacket. It arms first_above_time=300 ms. If no reset occurs, a qualifying observation at 299 ms is not yet eligible, while one at 300 ms is; equality with TARGET did not mean immediate dropping.", ["packet-sojourn", "codel-target", "codel-interval", "codel-above", "codel-eligible"]),
    ("codel-backlog-equality", "The low-backlog guard overrides a large sojourn", "A constructed RFC 8289 dequeue observes 20 ms of sojourn but leaves exactly 1500 bytes when maxpacket is 1500 bytes. The bytes<=maxpacket guard clears first_above_time and leaves that observation ineligible, even if a previous above-target deadline had already elapsed.", ["packet-sojourn", "nonstarvation-gate", "codel-reset", "codel-eligible"]),
    ("codel-previous-deadline", "Control-law time advances from its supplied schedule base", "An RFC 8289 control-law call with INTERVAL=100 ms, count=4, and scheduled base t=500 ms returns 550 ms. If the actual dequeue time is already 600 ms, the repeated-dropping path must not silently substitute 600 as that base and postpone the same scheduled event to 650 ms; eligibility still controls whether a due drop executes.", ["codel-interval", "codel-count", "codel-next", "codel-drop-state"]),
    ("deficit-packet-overshoot", "An indivisible packet can spend more than the remaining credit", "In the RFC 8290 byte-accounting example, a selected bucket has 400 bytes of positive credit and sends a packet charged 600 bytes. Its deficit becomes -200 bytes. On the next negative-deficit selection, adding a 1500-byte quantum gives 1300 bytes and rotates the bucket to the old-list tail instead of treating the earlier packet as illegal.", ["byte-quantum", "deficit", "deficit-exhausted", "flow-rotation"]),
    ("classic-ecn-episode", "Repeated echo packets do not represent repeated independent reductions", "A classic RFC 3168 connection receives a CE-marked data packet, sends ECE feedback, and the sender performs the applicable window reduction and emits CWR on new data. Further ECE ACKs for that same window are not instructions to halve on every ACK; after applicable CWR, later non-CE data no longer requires the old echo.", ["ce-mark", "ece-feedback", "cwnd-reduction", "cwr"]),
    ("rdma-local-completion-boundary", "Buffer ownership is different from remote business completion", "A Rev 1.7 verbs application observes successful completion of a non-inline signaled Send using a source buffer no other request still references. It may reuse that source buffer under the provider rule, but cannot conclude that the remote application finished processing the request. Generic RFC 5040 local completion gives even less remote-placement evidence, so it must not be substituted for a remote application acknowledgment.", ["completion", "buffer-reuse", "rdma-send", "remote-app-work"]),
    ("dpdk-burst-is-not-batch-fill", "Burst maxima and accepted counts have different meanings", "In a constructed DPDK v24.11 receive call requesting up to 32 packets, only seven completed packets are available, so the call need not wait for 25 more. In a separate transmit call requesting eight packets, a return count of five leaves three unaccepted packets with the caller; five accepted packets do not prove five peer deliveries.", ["burst-api", "batch-size", "tx-admission", "unaccepted-tx"]),
    ("pacing-rounded-into-burst", "Nominal microsecond gaps can collapse at the actual timer boundary", "A constructed pacer assigns packet releases at distinct times within one millisecond. Its actual scheduler rounds all those deadlines to the same millisecond boundary and releases the queued packets together. The written schedule still contains gaps, but the measured departures form a burst at that timescale, so the assumed pacing mitigation does not apply there.", ["pacer", "packet-spacing", "timer-coalescing", "sender-burst"]),
]

